function legalQuick(fish){if(protectedFish(fish))return '<span class="pill pill-danger">GANZJÄHRIG GESCHONT · keine Entnahme</span>';let rule=DATA.rules.rules[S.state]?.[fish];return rule?`<span class="pill pill-lime">${h(rule[0]+' cm')} · ${h(rule[1])}</span>`:`<span class="pill">Vorschrift nicht hinterlegt (kein Freibrief)</span>`}
function photoValid(src){return typeof src==='string'&&/^data:image\/(jpeg|jpg|png|webp);base64,/i.test(src)}
