function topTrophies(){return [...S.trophies].filter(t=>Number(t.cm)>0).sort((a,b)=>Number(b.cm)-Number(a.cm)||Number(b.grams||0)-Number(a.grams||0)).slice(0,3)}
function rankCards(){const top=topTrophies();return `<div class="rank-grid">${[0,1,2].map(i=>{const t=top[i],lab=['GOLD','SILBER','BRONZE'][i];return `<div class="rank ${['gold','silver','bronze'][i]}"><div class="medal">${['🥇','🥈','🥉'][i]}</div><div class="place">${lab} · PLATZ ${i+1}</div>${t?`<strong>${h(t.fish)}</strong><div class="measure">${fmt(t.cm)} cm</div><div class="foot">${h(weightText(t.grams))} · ${dateDe(t.date)}</div>`:`<strong>Noch frei</strong><div class="foot">Erfasse einen Fang mit Länge</div>`}</div>`}).join('')}</div>`}
function catchesByWeight(){return S.trophies.filter(t=>Number(t.grams)>0)}
function getTotals(){return {weight:catchesByWeight().reduce((a,b)=>a+Number(b.grams),0),seconds:S.sessions.reduce((a,b)=>a+(Number(b.seconds)||0),0)}}
function homeView(){const tot=getTotals(),max=topTrophies()[0],last=[...S.trophies].sort((a,b)=>new Date(b.date)-new Date(a.date)).slice(0,3);return `<section class="hero"><div><div class="hero-label">DEIN ANGELABENTEUER BEGINNT HIER</div><h2>Jeder Fang.<br><strong>Eine Geschichte.</strong></h2><p>Dein persönliches Fangbuch, Fischlexikon und Angelschein-Trainer – alles an einem Ort, auch ohne Internet.</p><div class="flex wrap"><button class="button button-primary" data-action="openCatch">＋ Fang eintragen</button><button class="button button-outline" data-page="exam">Jetzt lernen →</button></div></div><img src="assets/petri-logo.webp" alt="Petri Heil Logo mit Hecht"></section><div class="grid cards4">${metric('DEINE FÄNGE',S.trophies.length,'Fische erfasst','♓',1)}${metric('GESAMTGEWICHT',fmt(tot.weight/1000,3),'kg · nur gewogene Fische','⚖')}${metric('BESTER FANG',max?fmt(max.cm):'–',max?'cm · '+h(max.fish):'Noch kein Rekord','♛')}${metric('ANGELZEIT',fmt(tot.seconds/3600,1),'Stunden · abgeschlossene Sessions','◷')}</div><section class="section"><div class="section-head"><h2>Dein Fang-Podium</h2><button class="text-button" data-page="trophies">Alle Trophäen →</button></div>${rankCards()}</section><div class="grid cards2 section"><div class="card"><div class="section-head"><h2>Letzte Fänge</h2><button class="text-button" data-page="trophies">Ansehen →</button></div>${last.length?last.map(t=>`<button class="session-row" style="background:none;color:inherit;border-left:0;border-top:0;border-right:0;width:100%;text-align:left" data-trophy="${h(t.id)}"><div><strong>${h(t.fish)}</strong><br><span>${dateDe(t.date)} · ${h(t.location||'Ohne Ort')}</span></div><strong class="accent">${fmt(t.cm)} cm</strong></button>`).join(''):empty('♓','Noch keine Fänge','Starte dein persönliches Fangbuch.','<button class="button button-primary" data-action="openCatch">Ersten Fang eintragen</button>')}</div><div class="card"><div class="section-head"><h2>Direkt loslegen</h2></div><div class="grid" style="gap:9px">${[['fish','♓','Fischarten entdecken','${DATA.fish.length} Einträge: Fisch- & Krebskunde'],['clock','◷','Angelzeit starten','Sitzungen und Zeiten erfassen'],['rules','⚖','Schonzeiten prüfen','Bundesland wählen und Quelle öffnen'],['spots','⌖','Angelspots verwalten','Orte mit GPS speichern']].map(([p,ic,t,sub])=>`<button class="session-row" style="background:none;color:inherit;border-left:0;border-top:0;border-right:0;width:100%;text-align:left" data-page="${p}"><span style="font-size:25px">${ic}</span><span class="grow"><strong>${t}</strong><br><span>${sub}</span></span><b>→</b></button>`).join('')}</div></div></div><div class="warning section">Rechtliches: Schonzeiten, Mindestmaße und Entnahmeregeln gelten je nach Bundesland, Küste und Gewässer. Nur NRW und Bayern besitzen hier eine geprüfte Teilauswahl (Stand der Quellen: Oktober 2026). Offline gespeicherte Werte können veralten.</div>`}
function trophiesView(){const sort=S.trophies.slice().sort((a,b)=>new Date(b.date)-new Date(a.date));const view=trophyFilter==='Alle'?sort:sort.filter(x=>x.fish===trophyFilter);const fishSelect=[...new Set(S.trophies.map(t=>t.fish))].sort((a,b)=>a.localeCompare(b,'de'));return `<div class="section-head"><div><h2>Deine persönlichen Rekorde</h2><p>Ranking nach Länge; bei gleicher Länge nach Gewicht.</p></div><button class="button button-primary" data-action="openCatch">＋ Neuer Fang</button></div>${rankCards()}<section class="section"><div class="toolbar"><div class="grow"><h2>Fangbuch <span class="pill">${S.trophies.length} Einträge</span></h2></div><select class="control select-compact" id="trophy-filter"><option>Alle</option>${fishSelect.map(f=>`<option ${trophyFilter===f?'selected':''}>${h(f)}</option>`).join('')}</select></div>${view.length?`<div class="trophy-grid">${view.map(t=>`<button class="trophy" data-trophy="${h(t.id)}"><div class="trophy-cover">${trophyPicture(t)}</div><div class="trophy-body"><h3>${h(t.fish)}</h3><div class="numbers"><span>${fmt(t.cm)} cm</span><span>${h(weightText(t.grams))}</span></div><div class="meta">${dateDe(t.date)} · ${h(t.location||'Ort nicht angegeben')}</div></div></button>`).join('')}</div>`:empty('♛','Keine Fänge vorhanden','Fänge werden mit Bildern und Messwerten direkt hier angezeigt.','<button class="button button-primary" data-action="openCatch">Fang hinzufügen</button>')}</section>`}
// Local AI-generated illustrative species/product depictions. Not proof of identification.
const LOCAL_AI_IMAGES={"fish:f1":"assets/ki-bilder/hecht.webp","fish:f2":"assets/ki-bilder/zander.webp","fish:f3":"assets/ki-bilder/flussbarsch.webp","fish:f8":"assets/ki-bilder/karpfen.webp","fish:f5":"assets/ki-bilder/wels.webp","fish:f6":"assets/ki-bilder/aal.webp","fish:f23":"assets/ki-bilder/bachforelle.webp","fish:c1":"assets/ki-bilder/edelkrebs.webp","gear:5":"assets/ki-bilder/gummifisch.webp","gear:7":"assets/ki-bilder/spinner.webp"};
// Remote photographs remain a fallback for entries without local AI images.
const PHOTO_CACHE='petri-heil-real-photos-v1';
const COMMONS_GEAR_QUERIES=[
 ['spinning','fishing','rod'],['feeder','fishing','rod'],['carp','fishing','rod'],['fly','fishing','rod'],['surf','fishing','rod'],
 ['soft','plastic','fishing','lure'],['fishing','wobbler','lure'],['spinner','fishing','lure'],['boilie','carp','bait'],['corn','fishing','bait'],
 ['earthworm','fishing','bait'],['fishing','pilker','lure'],['monofilament','fishing','line'],['braided','fishing','line'],['fluorocarbon','fishing','line'],
 ['steel','fishing','leader'],['fishing','landing','net'],['fish','unhooking','mat'],['fishing','weighing','scale'],['fishing','hook','pliers'],['life','jacket']
];
let photoDownloadStop=false,photoObserver=null,photoLookupActive=new Set(),photoLookupAttempted=new Set();
const openLicenses=new Set(['cc0','cc-by','cc-by-sa']);
function shownPhotoFor(key){
 const saved=S.prefs?.realPhotos?.[key];
 if(saved?.source==='Eigener Upload'&&saved.url)return {url:saved.url,credit:'Eigenes Foto',license:'Privat',source:'Eigener Upload'};
 if(LOCAL_AI_IMAGES[key])return {url:LOCAL_AI_IMAGES[key],credit:'KI-generiert · Beispielbild, keine sichere Artbestimmung',license:'',source:'KI'};
 return saved?.url?saved:null;
}
function photoSlot(key,label,extra=''){
 const saved=shownPhotoFor(key),valid=saved&&typeof saved.url==='string'&&(saved.url.startsWith('assets/ki-bilder/')||saved.url.startsWith('data:image/')||saved.url.startsWith('https://'));
 const ai=saved?.source==='KI';
 const photo=valid?`<img src="${h(saved.url)}" alt="${ai?'KI-generiertes Beispielbild':'Fotografie'}: ${h(label)}" loading="lazy" decoding="async">`:'';
 const credit=valid?`<span class="photo-credit">${h(saved.credit||'Eigene Fotografie')}${saved.license?' · '+h(saved.license):''}</span>${!ai&&/^https:\/\//.test(saved.page||'')&&(!key.startsWith('fish:')||extra)?`<a class="photo-source" target="_blank" rel="noopener noreferrer" href="${h(saved.page)}">Bildquelle ansehen ↗</a>`:''}`:'';
 return `<div class="photo-host ${extra} ${ai?'photo-ai':''}" data-photo-key="${h(key)}"><div class="photo-placeholder" ${valid?'hidden':''}><span class="photo-camera">▧</span><span>Foto ${saved?.missing?'nicht gefunden':navigator.onLine?'wird gesucht':'offline nicht gespeichert'}</span></div><div class="photo-content">${photo}</div><div class="photo-info">${credit}</div></div>`;
}
function displayPhoto(key){const match=shownPhotoFor(key);if(!match)return;
 for(const el of document.querySelectorAll('.photo-host')){if(el.dataset.photoKey!==key)continue;
 const placeholder=el.querySelector('.photo-placeholder');if(placeholder)placeholder.hidden=Boolean(match.url);
 const content=el.querySelector('.photo-content'),info=el.querySelector('.photo-info');
 if(!match.url){if(placeholder)placeholder.lastElementChild.textContent='Kein eindeutig zugeordnetes Foto verfügbar';continue}
 const ai=match.source==='KI';el.classList.toggle('photo-ai',ai);
 if(content)content.innerHTML=`<img src="${h(match.url)}" alt="${ai?'KI-generiertes Beispielbild':'Echte Fotografie'}" loading="lazy" decoding="async">`;
 if(info)info.innerHTML=`<span class="photo-credit">${h(match.credit||(ai?'KI-generiertes Beispielbild':'Eigene Fotografie'))}${match.license?' · '+h(match.license):''}</span>${!ai&&/^https:\/\//.test(match.page||'')&&!el.closest('.fish-card')?`<a class="photo-source" href="${h(match.page)}" target="_blank" rel="noopener noreferrer">Bildquelle ansehen ↗</a>`:''}`;
 }
}
function startVisiblePhotos(){
 if(!photoObserver&&'IntersectionObserver'in window){photoObserver=new IntersectionObserver(entries=>{for(const entry of entries){if(entry.isIntersecting){photoObserver.unobserve(entry.target);maybeResolvePhoto(entry.target.dataset.photoKey)}}},{rootMargin:'400px'});}
 for(const el of document.querySelectorAll('.photo-host')){
   const key=el.dataset.photoKey,photo=shownPhotoFor(key);if(photo?.url){displayPhoto(key);continue};
   if(!navigator.onLine||photo?.missing)continue;
   if(photoObserver)photoObserver.observe(el);else maybeResolvePhoto(key)
 }
}
async function getPhotoJSON(url){const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),13000);try{const res=await fetch(url,{signal:ctrl.signal,cache:'no-store'});if(!res.ok)throw Error('HTTP '+res.status);return await res.json()}finally{clearTimeout(timer)}}
function correctLatin(given,got){return String(given||'').trim().toLocaleLowerCase('en')===String(got||'').trim().toLocaleLowerCase('en')}
function usablePhoto(photo){return photo&&openLicenses.has(String(photo.license_code||'').toLowerCase())&&/^https:\/\//.test(photo.medium_url||photo.url||'')}
async function fishRealPhoto(f){
  const latin=f.latin.trim(),j=await getPhotoJSON('https://api.inaturalist.org/v1/taxa/autocomplete?per_page=10&q='+encodeURIComponent(latin));
  const taxon=(j.results||[]).find(x=>correctLatin(latin,x.name)&&x.is_active!==false&&['species','subspecies'].includes(x.rank));
  if(!taxon)return null;
  let photo=taxon.default_photo;
  if(!usablePhoto(photo)){
    const obs=await getPhotoJSON(`https://api.inaturalist.org/v1/observations?taxon_id=${taxon.id}&quality_grade=research&photos=true&photo_license=cc0%2Ccc-by%2Ccc-by-sa&per_page=12`);
    for(const o of obs.results||[]){if(!correctLatin(o.taxon?.name,latin))continue;photo=(o.photos||[]).find(usablePhoto);if(photo)break;}
  }
  if(!usablePhoto(photo))return null;
  const url=photo.medium_url||(photo.url||'').replace('/square.','/medium.');
  return {url,credit:String(photo.attribution||'iNaturalist-Fotograf').slice(0,200),license:String(photo.license_code).toUpperCase(),page:'https://www.inaturalist.org/taxa/'+taxon.id,latin,source:'iNaturalist'};
}
function decodeHtmlToText(v){const t=document.createElement('textarea');t.innerHTML=String(v||'').replace(/<[^>]*>/g,' ');return String(t.value||'').replace(/\s+/g,' ').trim().slice(0,150)}
async function gearRealPhoto(index){
 const words=COMMONS_GEAR_QUERIES[index]||[];
 if(!words.length)return null;
 const query=words.join(' ');
 const url='https://commons.wikimedia.org/w/api.php?origin=*&action=query&format=json&generator=search&gsrnamespace=6&gsrlimit=16&gsrsearch='+encodeURIComponent(query)+'&prop=imageinfo&iiprop=url%7Cmime%7Cextmetadata&iiurlwidth=820';
 const data=await getPhotoJSON(url),pages=Object.values(data.query?.pages||{});
 const options=[];
 for(const page of pages){const info=page.imageinfo?.[0],name=String(page.title||'').toLowerCase();if(!info||!/image\/(jpeg|webp)/i.test(info.mime||''))continue;
 if(/(draw|illustrat|diagram|scheme|painting|graphic|clipart|icon|logo|cartoon|vector|model|svg)/.test(name))continue;
 const met=info.extmetadata||{},lic=decodeHtmlToText(met.LicenseShortName?.value).toUpperCase();
 if(!/(CC0|PUBLIC DOMAIN|CC BY|CC-BY|PD-)/.test(lic)||/(NC|ND)/.test(lic))continue;
 const clean=name.replace(/file:|[_.\d-]/g,' '),score=words.reduce((n,w)=>n+(clean.includes(w)?1:0),0);
 if(score<Math.min(2,words.length))continue;
 const image=info.thumburl||info.url;
 if(!image?.startsWith('https://'))continue;
 options.push({score,url:image,credit:decodeHtmlToText(met.Artist?.value)||'Fotograf auf Wikimedia Commons',license:lic,page:info.descriptionurl||('https://commons.wikimedia.org/wiki/'+encodeURIComponent(page.title)),source:'Wikimedia Commons'});
 }
 options.sort((a,b)=>b.score-a.score);return options[0]||null;
}
async function maybeResolvePhoto(key,forced=false){
 if(!key||!navigator.onLine||photoLookupActive.has(key)||!/^fish:(f|s|c)\d+$|^gear:\d{1,2}$/.test(key))return;
 if(LOCAL_AI_IMAGES[key])return;
 if(!forced&&(S.prefs?.realPhotos?.[key]||photoLookupAttempted.has(key)))return;
 photoLookupActive.add(key);photoLookupAttempted.add(key);
 try{
  let result=null;
  if(key.startsWith('fish:')){const f=DATA.fish.find(f=>'fish:'+f.id===key);if(f)result=await fishRealPhoto(f)}
  else result=await gearRealPhoto(Number(key.slice(5)));
  // Do not overwrite manually attached photography.
  if(S.prefs.realPhotos[key]?.source==='Eigener Upload')return;
  S.prefs.realPhotos[key]=result||{missing:true};
  await save();displayPhoto(key);
  if(result?.url)cacheRemotePhoto(result.url).catch(()=>{});
 }catch(err){
  // Network/server failures are not mistaken for a genuinely missing photo.
  if(document.querySelector(`[data-photo-key="${key}"]`)?.querySelector('.photo-placeholder span:last-child')){
   const el=document.querySelector(`[data-photo-key="${key}"] .photo-placeholder span:last-child`);
   if(el)el.textContent='Foto aktuell nicht verfügbar';
  }
 }finally{photoLookupActive.delete(key)}
}
async function cacheRemotePhoto(url){if(!('caches'in window)||!navigator.onLine)return false;
 const cache=await caches.open(PHOTO_CACHE);const existing=await cache.match(url);if(existing)return true;
 const u=new URL(url);if(!['static.inaturalist.org','inaturalist-open-data.s3.amazonaws.com','upload.wikimedia.org'].includes(u.hostname))return false;
 const response=await fetch(url,{mode:'no-cors',credentials:'omit'});if(!response.ok&&response.type!=='opaque')return false;
 await cache.put(url,response.clone());return true;
}
async function prepareAllPhotos(){if(!navigator.onLine)return toast('Für die Fotovorbereitung ist Internet nötig.');photoDownloadStop=false;
 const items=[...DATA.fish.map(f=>'fish:'+f.id),...GEAR.map((_,i)=>'gear:'+i)];let found=0,missing=0,stored=0;
 const status=()=>$('#photo-progress');
 for(let i=0;i<items.length;i++){
  if(photoDownloadStop)break;
  const key=items[i],item=S.prefs.realPhotos[key];
  if(LOCAL_AI_IMAGES[key]){found++;stored++;if(status())status().textContent=`${i+1}/${items.length} geprüft · ${found} Fotos/Bilder vorhanden · ${stored} offline verfügbar · ${missing} ohne Bild`;continue;}
  if(!item?.url&&!item?.missing)await maybeResolvePhoto(key,true);
  const photo=S.prefs.realPhotos[key];if(photo?.url){found++;try{if(await cacheRemotePhoto(photo.url))stored++}catch(e){}}
  else missing++;
  if(status())status().textContent=`${i+1}/${items.length} geprüft · ${found} Fotos gefunden · ${stored} offline zwischengespeichert · ${missing} ohne Foto`;
  await new Promise(resolve=>setTimeout(resolve,210));
 }
 if(status())status().textContent=(photoDownloadStop?'Abgebrochen. ':'Vorbereitung beendet. ')+`${found} Fotoquellen gefunden, ${stored} Fotodateien offline gespeichert; ${missing} fehlen. Offline-Verfügbarkeit hängt außerdem vom verfügbaren Gerätespeicher ab.`;
}
let ownPhotoTarget=null;
function chooseOwnPhoto(key){ownPhotoTarget=key;let inp=$('#own-reference-photo');if(!inp){inp=document.createElement('input');inp.type='file';inp.id='own-reference-photo';inp.accept='image/jpeg,image/png,image/webp,image/heic,image/heif';inp.style.display='none';document.body.appendChild(inp)}inp.click()}
async function processOwnPhoto(file){if(!file||!ownPhotoTarget)return;
 try{const uri=await imageToDataURL(file);S.prefs.realPhotos[ownPhotoTarget]={url:uri,credit:'Privates Foto',license:'Eigenes Foto',source:'Eigener Upload'};await save();displayPhoto(ownPhotoTarget);toast('Echtes Foto zugeordnet und gespeichert.');}
 catch(e){toast('Foto konnte nicht gelesen werden: '+e.message)}finally{ownPhotoTarget=null}
}
function fishIllustration(f,extraClass=''){return photoSlot('fish:'+f.id,f.name,extraClass)}
function gearIllustration(entry){return photoSlot('gear:'+GEAR.indexOf(entry),entry[2],'gear-photo-slot')}
function fishView(){let groups=['Alle',...new Set(DATA.fish.map(f=>f.group))];return `<div class="section-head"><div><h2>Fisch- & Krebskunde</h2><p>${DATA.fish.length} Einträge – Fische und Krebse, Köder, Gefahren und Verzehrhinweise.</p></div><span class="pill pill-lime">KI-BILDER: SOFORT OFFLINE · REST: FOTOS ONLINE</span></div><div class="warning floating-note">KI-generierte Artenbilder sind als solche gekennzeichnet und offline verfügbar. Sie dienen der Veranschaulichung, nicht als sichere Bestimmungsgrundlage. Weitere echte Naturfotos werden anhand wissenschaftlicher Namen gesucht und mit Quelle und Lizenz ausgewiesen. Ein umfangreicher Lernkatalog, keine vollständige amtliche Artenliste. Ein Fisch gilt nicht automatisch als entnehmbar oder essbar. Artenschutz, Schonzeiten, örtliche Verbote und ggf. Schadstoffbelastung prüfen.</div><div class="toolbar"><div class="searchbar"><span>⌕</span><input id="fish-search" class="control" value="${h(fishFilter.search)}" placeholder="Fischname oder wissenschaftlicher Name" autocomplete="off"></div><select class="control select-compact" id="fish-water"><option ${fishFilter.water==='Alle'?'selected':''}>Alle</option><option ${fishFilter.water==='Süßwasser'?'selected':''}>Süßwasser</option><option ${fishFilter.water==='Salzwasser'?'selected':''}>Salzwasser</option></select><select class="control select-compact" id="fish-group">${groups.map(x=>`<option ${fishFilter.group===x?'selected':''}>${h(x)}</option>`).join('')}</select></div><div class="mini-label" id="fish-count"></div><div id="fish-list" style="margin-top:12px"></div>`}
function updateFishList(){const target=$('#fish-list');if(!target)return;let search=fishFilter.search.toLocaleLowerCase('de-DE').trim();let filtered=DATA.fish.filter(f=>(fishFilter.water==='Alle'||f.water===fishFilter.water)&&(fishFilter.group==='Alle'||f.group===fishFilter.group)&&(!search||(f.name+' '+f.latin+' '+f.group).toLocaleLowerCase('de-DE').includes(search)));$('#fish-count').textContent=`${filtered.length} Treffer`;target.innerHTML=filtered.length?`<div class="fish-grid">${filtered.map(f=>`<button class="fish-card" data-fish="${h(f.id)}">${fishIllustration(f)}<div class="fish-card-top"><div><h3>${h(f.name)}</h3><em>${h(f.latin)}</em></div></div><div class="fish-card-footer"><span>${protectedFish(f.name)?'GESCHÜTZT':h(f.group)}</span><strong>Mehr ansehen →</strong></div></button>`).join('')}</div>`:empty('⌕','Keine Treffer','Versuche einen anderen Suchbegriff oder Filter.')}
function openFish(fishId){let f=DATA.fish.find(x=>x.id===fishId);if(!f)return;let link=DATA.rules.sources[S.state];openModal(`<div class="modal-head"><div><div class="eyebrow">FISCHKUNDE · ${h(f.water.toUpperCase())}</div><h2>${h(f.name)}</h2><span class="muted small"><i>${h(f.latin)}</i> · ${h(f.group)}</span></div><button class="icon-button" data-action="closeModal">✕</button></div><div class="modal-body"><figure class="species-detail-image">${fishIllustration(f,'fish-art-detail')}<figcaption>KI-Bilder sind nur beispielhafte Darstellungen, keine sicheren Bestimmungsmerkmale. Externe Fotos enthalten gegebenenfalls Quellenangaben.</figcaption></figure><button class="button button-outline button-small" data-action="ownPhoto" data-photo-key="fish:${h(f.id)}">Eigenes echtes Foto zuordnen</button><p>${h(f.desc)}</p><div class="grid cards2"><div class="card"><div class="mini-label">VORKOMMEN</div><p class="small">${h(f.habitat)}</p></div><div class="card"><div class="mini-label">KÖDER / MONTAGEN</div><p class="small">${h(f.baits)}</p></div><div class="card"><div class="mini-label">STACHELN / GEFAHREN</div><p class="small">${f.venom?'Giftige Stacheln / Giftgefahr: Ja. ':'Giftwirkung nicht belegt (keine Garantie für Ungefährlichkeit). '}${h(f.hazard)}</p></div><div class="card"><div class="mini-label">VERZEHR</div><p class="small">${h(f.food)}</p></div></div><div class="divider"></div><h3>Schonmaße & Zeiten · ${h(S.state)}</h3><div style="margin:12px 0">${legalQuick(f.name)}</div>${protectedFish(f.name)?'<div class="warning"><strong>Ganzjähriger Entnahmeschutz.</strong> Dieser Fisch darf im genannten Geltungsbereich nicht entnommen werden. Die genaue Regelung und regionale Einschränkungen in der Quelle nachlesen.</div>':''}<div class="warning">Angaben sind nur ein Teilauszug aus dem Landesrecht, keine Freigabe. Fischereierlaubnis, Schutzgebiet, EU-/Küstenregeln und Gewässerordnung können vorgehen.</div>${link?`<p class="small"><a href="${h(link)}" target="_blank" rel="noopener noreferrer">Amtlichen Rechtstext öffnen ↗ (Internet nötig)</a></p>`:''}</div><div class="modal-actions"><button class="button button-ghost" data-action="closeModal">Schließen</button><button class="button button-primary" data-action="openCatch" data-prefish="${h(f.name)}">Fang dieser Art erfassen</button></div>`);setTimeout(startVisiblePhotos,0)}
function rulesView(){const rules=DATA.rules.rules[S.state]||null,url=DATA.rules.sources[S.state];return `<div class="section-head"><div><h2>Schonzeiten & Mindestmaße</h2><p>Bundesland wählen – nur geprüfte Teilauszüge werden mit Zahlen angezeigt.</p></div></div><div class="toolbar"><select class="control" style="max-width:320px" id="state-select">${DATA.rules.states.map(st=>`<option ${S.state===st?'selected':''}>${h(st)}</option>`).join('')}</select>${url?`<a class="button button-outline" href="${h(url)}" target="_blank" rel="noopener noreferrer">Amtliche Quelle ↗</a>`:''}</div><div class="warning floating-note"><strong>Wichtig:</strong> Alle Werte sind ohne Gewähr auf Aktualität am Fangtag. Gewässerspezifische strengere Regeln, Schongebiete, Fanglimits und EU-/Küstenfischerei können hinzukommen. ${h(DATA.rules.note)}</div>${rules?`<div class="card"><div class="flex wrap between"><h2>Geprüfte Teilauswahl · ${h(S.state)}</h2><span class="pill pill-lime">Quelle geprüft: 09.10.2026</span></div><div class="table-scroll"><table class="table"><thead><tr><th>Art</th><th>Mindestmaß</th><th>Schonzeit / Einschränkung</th></tr></thead><tbody>${Object.entries(rules).sort((a,b)=>a[0].localeCompare(b[0],'de')).map(([f,[cm,season]])=>`<tr><td><strong>${h(f)}</strong></td><td class="nowrap">${fmt(cm,0)} cm</td><td>${h(season)}</td></tr>`).join('')}</tbody></table></div>${DATA.rules.protected?.[S.state]?.length?`<div class="protected-list"><h3>Ganzjährig geschützte Arten (Teilauswahl)</h3><p class="muted small">${h(DATA.rules.protectedNote?.[S.state]||'Räumlichen Geltungsbereich beachten.')}</p><div class="chip-cloud">${DATA.rules.protected[S.state].map(n=>`<span class="pill pill-danger">${h(n)}</span>`).join('')}</div></div>`:''}<p class="small muted">${S.state==='Bayern'?'Die allgemeine bayerische Anlage unterscheidet teilweise Flussgebietseinheiten. Das Bodensee-Sonderrecht und andere abweichende Regeln sind hier nicht abgebildet.':'Die Angaben für NRW ergeben sich aus §§ 2–3 der LFischVO; zusätzliche europäische/regionale Bestimmungen sind möglich.'}</p></div>`:`<div class="card">${empty('⚖','Keine geprüften Landeswerte hinterlegt','Für dieses Bundesland wurden bewusst keine Zahlen erfunden. Prüfe die aktuelle Landesfischereiverordnung, die zuständige Fischereibehörde und die Gewässerordnung vor jedem Angeltrip.')}<p class="muted small">Du kannst trotzdem im Fischlexikon und im Angelschein-Trainer mit bundesweiten Grundlagen arbeiten.</p></div>`}<div class="card section"><h3>Prüfungs- und Rechtsquellen</h3><p class="muted small">NRW: Landesfischereiverordnung (Fassung 03.07.2026) und Fischerprüfungsordnung. Bayern: AVBayFiG Anlage (ab 01.06.2025). Schleswig-Holstein: Hinweise der Landesverwaltung vom 26.02.2026.</p><div class="flex wrap">${[['NRW Landesrecht','https://recht.nrw.de/lrgv/rechtsverordnung/03072026-landesfischereiverordnung-lfischvo/'],['NRW Prüfung','https://recht.nrw.de/lrgv/rechtsverordnung/03072026-verordnung-ueber-die-fischerpruefung/'],['Bayern Anlage','https://www.gesetze-bayern.de/Content/Document/BayAVFiG-ANL_1'],['SH Landesinfos','https://www.schleswig-holstein.de/DE/fachinhalte/F/fischerei/gesetzeVerordnungen']].map(([t,l])=>`<a class="button button-ghost button-small" href="${l}" target="_blank" rel="noopener noreferrer">${t} ↗</a>`).join('')}</div></div>`}
function questionPool(){return DATA.questions.filter(q=>!q.state||q.state===S.state)}
function shuffled(a){return [...a].sort(()=>Math.random()-.5)}
function makeQuiz(type){const pool=questionPool();let pick=[];if(type==='exam'&&S.state==='Nordrhein-Westfalen'){for(const cat of ['Allgemeine Fischkunde','Spezielle Fischkunde','Gewässerkunde und Fischhege','Natur- und Tierschutz','Gerätekunde','Gesetzeskunde'])pick.push(...shuffled(pool.filter(x=>x.category===cat)).slice(0,10))}else pick=shuffled(pool).slice(0,type==='exam'?30:20);return{type,questions:shuffled(pick).map(q=>({...q,shown:shuffled(q.options.map((txt,i)=>({txt,correct:i===q.answer})))})),answers:{},index:0,started:Date.now(),duration:type==='exam'?(S.state==='Nordrhein-Westfalen'?3600:1800):0,finished:false,state:S.state}}
function examView(){if(quiz?.finished)return examResultView();if(quiz)return questionView();return `<div class="section-head"><div><h2>Angelschein-Trainer</h2><p>${DATA.questions.length} selbst formulierte Lernfragen · nach Bundesland gefiltert.</p></div><span class="pill pill-lime">OFFLINE TRAINING</span></div><div class="warning floating-note">Diese App enthält <strong>eigene Übungsfragen, keinen vollständigen amtlichen Fragenkatalog</strong>. Der Prüfungsmodus ist eine Simulation und ersetzt weder amtliche Prüfungsunterlagen noch die praktische Prüfung. In anderen Ländern als NRW/Bayern sind keine spezifisch geprüften Landesrechtsfragen enthalten.</div><div class="grid cards2"><div class="card"><span class="pill pill-lime">LERNSYSTEM</span><h2 style="font-size:25px;margin:16px 0 9px">Üben & Verstehen</h2><p class="muted">20 zufällige Fragen mit direktem Feedback und Erklärungen zu den sechs Themengebieten.</p><div class="divider"></div><button class="button button-primary" data-action="startLearn">Training starten →</button></div><div class="card"><span class="pill pill-gold">PRÜFUNGSMODUS</span><h2 style="font-size:25px;margin:16px 0 9px">Wissen testen</h2><p class="muted">${S.state==='Nordrhein-Westfalen'?'60 Fragen, 60 Minuten. Je zehn Fragen aus sechs Bereichen, in Anlehnung an die NRW-Prüfungsordnung.':'30 Übungsfragen, 30 Minuten. Kein amtliches Prüfungsformat.'} Auswertung nach Abschluss.</p><div class="divider"></div><button class="button button-outline" data-action="startExam">Simulation starten →</button></div></div><div class="card section"><div class="section-head"><h2>Dein Bundesland</h2><span class="pill">${h(S.state)}</span></div><select class="control" style="max-width:340px" id="state-select">${DATA.rules.states.map(st=>`<option ${S.state===st?'selected':''}>${h(st)}</option>`).join('')}</select><p class="small muted" style="margin:12px 0 0">${S.state==='Nordrhein-Westfalen'?'NRW: Schriftliche Prüfung gemäß Prüfungsordnung mit 60 Fragen in 60 Minuten; zusätzlich praktischer Prüfungsteil.':S.state==='Bayern'?'Bayerische Landesfragen: amtlich geprüfte Rechtsauszüge; die echte Prüfung ist umfangreicher.':'Bundesweite Grundlagenfragen vorhanden; keine geprüften landesspezifischen Prüfungstexte.'}</p></div><div class="card section"><h2>Deine letzten Ergebnisse</h2>${S.examHistory.length?S.examHistory.slice(-5).reverse().map(e=>`<div class="session-row"><div><strong>${e.type==='exam'?'Prüfungssimulation':'Training'}</strong><br><span>${dateDe(e.date)} · ${h(e.state)}</span></div><strong class="accent">${fmt(100*e.correct/e.total,0)} %</strong></div>`).join(''):empty('▤','Noch kein Test','Deine Prüfungsergebnisse werden lokal gespeichert.')}</div>`}
function questionView(){const q=quiz.questions[quiz.index],idx=quiz.index,selected=quiz.answers[q.id],isLearn=quiz.type==='learn';return `<div class="quiz-panel"><div class="flex between wrap" style="margin-bottom:14px"><span class="pill ${quiz.type==='exam'?'pill-gold':'pill-lime'}">${quiz.type==='exam'?'PRÜFUNGSSIMULATION':'LERNSYSTEM'} · ${h(quiz.state)}</span><span class="mini-label" id="quiz-timer">${quiz.duration?timeText(Math.max(0,quiz.duration-Math.floor((Date.now()-quiz.started)/1000))):'Ohne Zeitlimit'}</span></div><div class="progress-track"><div style="width:${Math.round((idx+1)/quiz.questions.length*100)}%"></div></div><div class="flex between wrap" style="margin:17px 0"><span class="mini-label">FRAGE ${idx+1} VON ${quiz.questions.length}</span><span class="pill">${h(q.category)}</span></div><div class="card"><div class="quiz-question">${h(q.q)}</div>${q.shown.map((o,i)=>{let klass=selected===i?'selected':'';if(isLearn&&selected!==undefined)klass=o.correct?'correct':selected===i?'wrong':'';return `<button data-quiz-answer="${i}" class="quiz-option ${klass}" ${isLearn&&selected!==undefined?'disabled':''}><span class="option-letter">${'ABCD'[i]}</span>${h(o.txt)}</button>`}).join('')}${isLearn&&selected!==undefined?`<div class="explain"><strong>${q.shown[selected]?.correct?'Richtig!':'Nicht ganz.'}</strong><p style="margin:7px 0 0">${h(q.explanation)}</p></div>`:''}<div class="divider"></div><div class="flex between wrap"><button class="button button-ghost" data-action="abortQuiz">Abbrechen</button><div class="flex wrap">${quiz.type==='exam'&&idx>0?`<button class="button button-ghost" data-action="prevQuestion">← Zurück</button>`:''}<button class="button button-primary" data-action="nextQuestion" ${selected===undefined?'disabled':''}>${idx===quiz.questions.length-1?'Auswerten':'Weiter →'}</button></div></div></div></div>`}
function finishQuiz(){if(!quiz||quiz.finished)return;quiz.finished=true;let correct=quiz.questions.filter(q=>q.shown[quiz.answers[q.id]]?.correct).length;S.examHistory.push({id:id(),date:new Date().toISOString(),type:quiz.type,state:quiz.state,total:quiz.questions.length,correct});save();render()}
function examResultView(){let correct=quiz.questions.filter(q=>q.shown[quiz.answers[q.id]]?.correct).length,total=quiz.questions.length,pct=Math.round(correct/total*100),mistakes=quiz.questions.filter(q=>!q.shown[quiz.answers[q.id]]?.correct);let categories=[...new Set(quiz.questions.map(q=>q.category))],perCategory=categories.map(cat=>[cat,quiz.questions.filter(q=>q.category===cat&&q.shown[quiz.answers[q.id]]?.correct).length]),nrwRule=quiz.type==='exam'&&quiz.state==='Nordrhein-Westfalen'&&total===60;let theoryPassed=correct>=45&&perCategory.every(([cat,n])=>n>=6);return `<div class="quiz-panel"><div class="card" style="text-align:center"><div style="font-size:45px">${pct>=75?'✦':'▤'}</div><p class="eyebrow">AUSWERTUNG</p><h2 style="font-size:32px">${pct}% richtig</h2><div class="big-stat accent">${correct} / ${total}</div><p class="muted">${nrwRule?(theoryPassed?'Schriftliche NRW-Mindestanforderungen in dieser Simulation erreicht.':'Schriftliche NRW-Mindestanforderungen nicht erreicht (mindestens 45 insgesamt und mindestens 6 pro Gebiet).'):(pct>=75?'Gute Leistung in dieser Übung.':'Du kannst Wissenslücken gezielt wiederholen.')} Dies ist keine amtliche Bestehensbewertung; praktische Prüfung ist nicht enthalten.</p>${nrwRule?`<div class="explain">${perCategory.map(([cat,n])=>`<div class="session-row"><span>${h(cat)}</span><strong>${n}/10 ${n>=6?'✓':'✕'}</strong></div>`).join('')}</div>`:''}<div class="flex wrap" style="justify-content:center"><button class="button button-primary" data-action="finishGoHome">Neuen Test wählen</button><button class="button button-ghost" data-action="startLearn">Noch einmal üben</button></div></div><div class="card section"><h2>Fragen mit Nachholbedarf (${mistakes.length})</h2>${mistakes.length?mistakes.map(q=>`<div class="session-row" style="display:block"><strong>${h(q.q)}</strong><p class="small" style="margin:6px 0"><span>Richtige Antwort: ${h(q.shown.find(o=>o.correct)?.txt)}</span></p><p class="small muted" style="margin:0">${h(q.explanation)}</p></div>`).join(''):empty('✦','Alle Fragen richtig','Dein Übungsdurchgang war fehlerfrei.')}</div></div>`}
function timerElapsed(){if(!S.timer.running)return 0;let end=S.timer.paused?new Date(S.timer.pausedAt).getTime():Date.now();return Math.max(0,Math.floor((end-new Date(S.timer.startedAt).getTime()-(S.timer.pausedMs||0))/1000))}
function clockView(){let running=S.timer.running,paused=S.timer.paused;return `<div class="section-head"><div><h2>Deine Angelzeit im Überblick</h2><p>Uhr starten, pausieren und Sessions mit Datum speichern.</p></div><span class="pill ${running?'pill-lime':''}">${running?(paused?'PAUSIERT':'LÄUFT'):'BEREIT'}</span></div><div class="grid cards2"><div class="card"><div class="clock-circle"><span class="clock-symbol">◷</span><span class="clock-caption">AKTUELLE ANGELZEIT</span><div class="time-clock" id="timer-clock">${timeText(timerElapsed())}</div><span class="mini-label">${running?datetimeDe(S.timer.startedAt):'Noch keine aktive Session'}</span></div><div class="flex wrap" style="justify-content:center">${!running?`<button class="button button-primary" data-action="timerStart">▶ Angelzeit starten</button>`:`<button class="button button-outline" data-action="timerToggle">${paused?'▶ Fortsetzen':'Ⅱ Pause'}</button><button class="button button-primary" data-action="timerStop">■ Beenden & speichern</button>`}</div><div class="divider"></div><div class="notice">Die Uhr läuft per Startzeitstempel weiter, wenn du die App schließt. Pausen werden abgezogen. Erst abgeschlossene Sessions werden gezählt.</div></div><div class="card"><h2>Zeitstatistik</h2>${sessionStats().map(([t,secs])=>`<div class="session-row"><strong>${t}</strong><strong class="accent">${durationText(secs)}</strong></div>`).join('')}<div class="divider"></div><h3>Letzte Angelzeiten <button class="text-button small" data-action="manualTime">＋ Zeit nachtragen</button></h3>${S.sessions.length?S.sessions.slice().sort((a,b)=>new Date(b.start)-new Date(a.start)).slice(0,7).map(s=>`<div class="session-row"><div><strong>${dateDe(s.start)}</strong><br><span>${datetimeDe(s.start)} – ${new Date(s.end).toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'})}</span></div><div class="text-right"><strong class="accent">${durationText(s.seconds)}</strong><br><button class="text-button small" data-delete-session="${h(s.id)}">Löschen</button></div></div>`).join(''):empty('◷','Noch keine Angelzeit','Starte die Uhr vor deinem nächsten Angelausflug.')}</div></div>`}
function mondayOf(d){let x=new Date(d),day=(x.getDay()+6)%7;x.setHours(0,0,0,0);x.setDate(x.getDate()-day);return x}
function periodMatch(date,period){let v=new Date(date),now=new Date();if(isNaN(v))return false;if(period==='Tag')return v.toDateString()===now.toDateString();if(period==='Woche')return v>=mondayOf(now)&&v<mondayOf(new Date(mondayOf(now).getTime()+7*86400000));if(period==='Monat')return v.getFullYear()===now.getFullYear()&&v.getMonth()===now.getMonth();if(period==='Jahr')return v.getFullYear()===now.getFullYear();return true}
function periodBounds(period,now=new Date()){let start=new Date(now);start.setHours(0,0,0,0);if(period==='Woche')start=mondayOf(now);if(period==='Monat')start.setDate(1);if(period==='Jahr')start.setMonth(0,1);let end=new Date(start);if(period==='Tag')end.setDate(end.getDate()+1);if(period==='Woche')end.setDate(end.getDate()+7);if(period==='Monat')end.setMonth(end.getMonth()+1);if(period==='Jahr')end.setFullYear(end.getFullYear()+1);return [start.getTime(),end.getTime()]}
function sessionStats(){return ['Tag','Woche','Monat','Jahr'].map(p=>{const [start,end]=periodBounds(p);let ms=S.sessions.reduce((total,s)=>{let segs=arr(s.segments).length?s.segments:[[s.start,s.end||new Date(new Date(s.start).getTime()+Number(s.seconds)*1000).toISOString()]];return total+segs.reduce((v,[a,b])=>v+Math.max(0,Math.min(new Date(b).getTime(),end)-Math.max(new Date(a).getTime(),start))||v,0)},0);return [p,Math.round(ms/1000)]})}
function weightStats(){let c=catchesByWeight();return ['Tag','Woche','Monat','Jahr'].map(p=>[p,c.filter(t=>periodMatch(t.date,p)).reduce((a,t)=>a+Number(t.grams),0)])}
function bars(data,unit='g'){let max=Math.max(1,...data.map(x=>x[1]));return data.map(([name,num])=>`<div class="bar-row"><strong>${h(name)}</strong><div class="bar-bg"><div class="bar-fill" style="width:${num?Math.max(3,Math.round(num/max*100)):0}%"></div></div><div class="text-right"><strong>${unit==='g'?weightText(num):durationText(num)}</strong></div></div>`).join('')}
function statsView(){let tot=getTotals(),fishes=catchesByWeight(),byFish=new Map();for(const t of fishes)byFish.set(t.fish,(byFish.get(t.fish)||0)+Number(t.grams));let summary=[...byFish].sort((a,b)=>b[1]-a[1]).slice(0,7);let months=Array.from({length:6},(_,i)=>{let d=new Date();d.setDate(1);d.setMonth(d.getMonth()-(5-i));return [d.toLocaleString('de-DE',{month:'short'}),fishes.filter(t=>{let x=new Date(t.date);return x.getFullYear()===d.getFullYear()&&x.getMonth()===d.getMonth()}).reduce((a,t)=>a+Number(t.grams),0)]});return `<div class="section-head"><div><h2>Deine Fangstatistik</h2><p>Gewicht nur aus Fängen mit einem positiven Gramm- oder Kilogrammwert.</p></div></div><div class="grid cards4">${metric('GEWICHT TOTAL',fmt(tot.weight/1000,3),'kg · '+fishes.length+' gewogene Fische','⚖',1)}${metric('GEWOGENE FÄNGE',fishes.length,'von '+S.trophies.length+' Fängen','♓')}${metric('ANGELZEIT TOTAL',fmt(tot.seconds/3600,1),'Stunden aus Sessions','◷')}${metric('Ø FANGGEWICHT',fishes.length?fmt((tot.weight/fishes.length)/1000,3):'0','kg je gewogenem Fang','▥')}</div><div class="grid cards2 section"><div class="card"><h2>Gewicht nach Zeitraum</h2><p class="small muted">Tag, Woche, Monat und Jahr</p>${bars(weightStats())}</div><div class="card"><h2>Angelzeit nach Zeitraum</h2><p class="small muted">Abgeschlossene Sessions</p>${bars(sessionStats(),'sec')}</div></div><div class="grid cards2 section"><div class="card"><h2>Fanggewicht – 6 Monate</h2><div class="bars-small">${months.map(([nm,n])=>`<div class="bar-column" title="${h(nm)}: ${h(weightText(n))}"><div class="bar" style="height:${Math.round(n/Math.max(1,...months.map(x=>x[1]))*105)}px"></div><label>${h(nm)}</label></div>`).join('')}</div></div><div class="card"><h2>Gewicht nach Fischart</h2>${summary.length?bars(summary):empty('▥','Noch keine Gewichtsdaten','Trage mindestens einen Fang mit Gramm oder Kilogramm ein.')}</div></div><div class="notice section">Nicht gewogene Fische zählen weiterhin im Fangbuch und im Längen-Ranking, aber nicht in die Gewichtsberechnung.</div>`}
